"use client";

import { CheckIcon, Info, MinusIcon } from "lucide-react";
import { Fragment, useState } from "react";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

type TierName = "Free" | "Pro" | "Premium";

interface Tier {
  name: string;
  price: string;
  annualPrice: string;
  description: string;
}

interface Feature {
  name: string;
  tiers: Partial<Record<TierName, boolean>>;
  tooltip?: string;
}

interface Section {
  name: string;
  features: Feature[];
}

const tiers: Tier[] = [
  {
    name: "Free",
    price: "$0",
    annualPrice: "$0",
    description: "Quis suspendisse ut fermentum neque vivamus.",
  },
  {
    name: "Pro",
    price: "$10",
    annualPrice: "$100",
    description: "Quis eleifend a tincidunt pellentesque.",
  },
  {
    name: "Premium",
    price: "$15",
    annualPrice: "$150",
    description: "Orci volutpat ut sed sed neque, dui eget.",
  },
];
const sections: Section[] = [
  {
    name: "Key Features",
    features: [
      {
        name: "Live Collaboration",
        tiers: { Free: true, Pro: true, Premium: true },
        tooltip: "Lorem ipsum dolor sit amet, consectetur",
      },
      {
        name: "Unlimited projects",
        tiers: { Free: true, Pro: true, Premium: true },
        tooltip: "Lorem ipsum dolor sit amet, consectetur",
      },
      {
        name: "Custom permissions",
        tiers: { Pro: true, Premium: true },
        tooltip: "Lorem ipsum dolor sit amet, consectetur",
      },
      {
        name: "Team members",
        tiers: {
          Premium: true,
        },
        tooltip: "Lorem ipsum dolor sit amet, consectetur",
      },
    ],
  },
  {
    name: "Reporting",
    features: [
      {
        name: "Basic reports",
        tiers: { Free: true, Pro: true, Premium: true },
        tooltip: "Lorem ipsum dolor sit amet, consectetur",
      },
      {
        name: "Advanced reports",
        tiers: { Pro: true, Premium: true },
        tooltip: "Lorem ipsum dolor sit amet, consectetur",
      },
      {
        name: "Custom reports",
        tiers: { Premium: true },
        tooltip: "Lorem ipsum dolor sit amet, consectetur",
      },
      {
        name: "Export data",
        tiers: { Premium: true },
        tooltip: "Lorem ipsum dolor sit amet, consectetur",
      },
    ],
  },
];

interface Pricing9Props {
  className?: string;
}

const Pricing9 = ({ className }: Pricing9Props) => {
  const [isAnnual, setIsAnnual] = useState(false);
  return (
    <section className={cn("py-24 sm:py-32", className)}>
      <div className="mx-auto max-w-7xl px-6 lg:px-8">
        <div className="mx-auto max-w-4xl text-center">
          <p className="mt-2 text-4xl font-bold tracking-tight sm:text-5xl">
            Choose Your Plan
          </p>
        </div>
        <p className="mx-auto mt-6 max-w-2xl text-center text-lg leading-8 text-muted-foreground">
          Distinctio et nulla eum soluta et neque labore quibusdam. Saepe et
          quasi.
        </p>
        <div className="mt-10 flex flex-col items-center gap-2 lg:hidden">
          <span className="flex items-center gap-3 text-base font-medium">
            Annual
            <Switch
              checked={isAnnual}
              onCheckedChange={() => setIsAnnual(!isAnnual)}
            />
            Monthly
          </span>
        </div>

        <div className="mx-auto mt-12 max-w-md space-y-8 sm:mt-16 lg:hidden">
          {tiers.map((tier) => (
            <Card key={tier.name} className="p-8">
              <CardHeader className="p-0">
                <div className="flex flex-col gap-2 text-center">
                  <span className="text-xl leading-7 font-bold uppercase">
                    <CardTitle className="text-xl">{tier.name}</CardTitle>
                  </span>
                  <span className="text-sm font-normal text-muted-foreground">
                    {tier.description}
                  </span>
                </div>
                <div className="flex flex-col justify-center gap-x-1 pt-8 text-center">
                  <span className="text-4xl font-bold">
                    {isAnnual ? tier.annualPrice : tier.price}
                  </span>
                  <span className="text-sm leading-6 text-muted-foreground">
                    /month
                  </span>
                </div>
              </CardHeader>
              <Button className="mt-8 w-full">Buy plan</Button>
              <CardContent className="p-0">
                <ul className="mt-10 space-y-4 text-sm leading-6">
                  <TooltipProvider>
                    {sections.map((section) => (
                      <li key={section.name}>
                        <ul role="list" className="space-y-4">
                          {section.features.map(
                            (feature) =>
                              feature.tiers[tier.name as TierName] && (
                                <li
                                  key={feature.name}
                                  className="flex items-center justify-between"
                                >
                                  <span className="flex items-center gap-3">
                                    <CheckIcon className="h-5 w-5 flex-none" />
                                    <span>{feature.name}</span>
                                  </span>
                                  <Tooltip>
                                    <TooltipTrigger>
                                      <Info className="ml-1 h-4 w-4 text-muted-foreground" />
                                    </TooltipTrigger>
                                    <TooltipContent>
                                      {feature.tooltip}
                                    </TooltipContent>
                                  </Tooltip>
                                </li>
                              ),
                          )}
                        </ul>
                      </li>
                    ))}
                  </TooltipProvider>
                </ul>
              </CardContent>
            </Card>
          ))}
        </div>

        <div className="isolate mt-20 hidden lg:block">
          <div className="relative -mx-8">
            {tiers.map((tier, idx) => (
              <div
                className="absolute inset-x-4 inset-y-0 -z-10 flex"
                key={tier.name}
              >
                <div
                  className="flex w-1/4 px-4"
                  style={{
                    marginLeft: `${(idx + 1) * 25}%`,
                  }}
                >
                  <div className="w-full border-x" />
                </div>
              </div>
            ))}
            <table className="w-full table-fixed border-separate border-spacing-x-8 text-left">
              <thead>
                <tr>
                  <td />
                  {tiers.map((tier) => (
                    <th key={tier.name} className="px-6 pt-6 xl:px-8 xl:pt-8">
                      <div className="flex flex-col gap-2 text-center">
                        <span className="text-xl leading-7 font-bold uppercase">
                          {tier.name}
                        </span>
                        <span className="text-sm font-normal text-muted-foreground">
                          {tier.description}
                        </span>
                      </div>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                <tr>
                  <th>
                    <div className="flex flex-col gap-2">
                      <p className="text-sm font-normal text-muted-foreground">
                        Billings
                      </p>
                      <span className="flex items-center gap-3 text-base font-medium">
                        Annual
                        <Switch
                          checked={isAnnual}
                          onCheckedChange={() => setIsAnnual(!isAnnual)}
                        />
                        Monthly
                      </span>
                    </div>
                  </th>
                  {tiers.map((tier) => (
                    <td key={tier.name} className="px-6 pt-10 xl:px-8">
                      <div className="flex flex-col justify-center gap-x-1 text-center">
                        <span className="text-4xl font-bold">
                          {isAnnual ? tier.annualPrice : tier.price}
                        </span>
                        <span className="text-sm leading-6 text-muted-foreground">
                          /month
                        </span>
                      </div>
                      <Button className="mt-8 w-full">Get Started</Button>
                    </td>
                  ))}
                </tr>
                {sections.map((section, sectionIdx) => (
                  <Fragment key={section.name}>
                    <tr>
                      <th
                        className={cn(
                          "pb-4 text-sm leading-6 font-semibold",
                          sectionIdx === 0 ? "pt-8" : "pt-16",
                        )}
                      >
                        {section.name}
                      </th>
                    </tr>
                    <TooltipProvider delayDuration={200}>
                      {section.features.map((feature) => (
                        <tr key={feature.name}>
                          <th className="flex items-center justify-between py-4 text-sm leading-6 font-normal">
                            {feature.name}
                            <Tooltip>
                              <TooltipTrigger>
                                <Info className="ml-1 h-4 w-4 text-muted-foreground hover:text-foreground" />
                              </TooltipTrigger>
                              <TooltipContent>{feature.tooltip}</TooltipContent>
                            </Tooltip>
                          </th>
                          {tiers.map((tier) => (
                            <td key={tier.name} className="px-6 py-4 xl:px-8">
                              <>
                                {feature.tiers[tier.name as TierName] ? (
                                  <CheckIcon className="mx-auto h-5 w-5" />
                                ) : (
                                  <MinusIcon className="mx-auto h-5 w-5 text-muted-foreground" />
                                )}
                              </>
                            </td>
                          ))}
                        </tr>
                      ))}
                    </TooltipProvider>
                  </Fragment>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </section>
  );
};
export { Pricing9 };

import { type ClassValue, clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot : "button"

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }

import * as React from "react"

import { cn } from "@/lib/utils"

function Card({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card"
      className={cn(
        "bg-card text-card-foreground flex flex-col gap-6 rounded-xl border py-6 shadow-sm",
        className
      )}
      {...props}
    />
  )
}

function CardHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-header"
      className={cn(
        "@container/card-header grid auto-rows-min grid-rows-[auto_auto] items-start gap-2 px-6 has-data-[slot=card-action]:grid-cols-[1fr_auto] [.border-b]:pb-6",
        className
      )}
      {...props}
    />
  )
}

function CardTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-title"
      className={cn("leading-none font-semibold", className)}
      {...props}
    />
  )
}

function CardDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-description"
      className={cn("text-muted-foreground text-sm", className)}
      {...props}
    />
  )
}

function CardAction({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn(
        "col-start-2 row-span-2 row-start-1 self-start justify-self-end",
        className
      )}
      {...props}
    />
  )
}

function CardContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-content"
      className={cn("px-6", className)}
      {...props}
    />
  )
}

function CardFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-footer"
      className={cn("flex items-center px-6 [.border-t]:pt-6", className)}
      {...props}
    />
  )
}

export {
  Card,
  CardHeader,
  CardFooter,
  CardTitle,
  CardAction,
  CardDescription,
  CardContent,
}

"use client"

import * as React from "react"
import * as SwitchPrimitive from "@radix-ui/react-switch"

import { cn } from "@/lib/utils"

function Switch({
  className,
  ...props
}: React.ComponentProps<typeof SwitchPrimitive.Root>) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      className={cn(
        "peer data-[state=checked]:bg-primary data-[state=unchecked]:bg-input focus-visible:border-ring focus-visible:ring-ring/50 dark:data-[state=unchecked]:bg-input/80 inline-flex h-[1.15rem] w-8 shrink-0 items-center rounded-full border border-transparent shadow-xs transition-all outline-none focus-visible:ring-[3px] disabled:cursor-not-allowed disabled:opacity-50",
        className
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className={cn(
          "bg-background dark:data-[state=unchecked]:bg-foreground dark:data-[state=checked]:bg-primary-foreground pointer-events-none block size-4 rounded-full ring-0 transition-transform data-[state=checked]:translate-x-[calc(100%-2px)] data-[state=unchecked]:translate-x-0"
        )}
      />
    </SwitchPrimitive.Root>
  )
}

export { Switch }

"use client"

import * as React from "react"
import * as TooltipPrimitive from "@radix-ui/react-tooltip"

import { cn } from "@/lib/utils"

function TooltipProvider({
  delayDuration = 0,
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Provider>) {
  return (
    <TooltipPrimitive.Provider
      data-slot="tooltip-provider"
      delayDuration={delayDuration}
      {...props}
    />
  )
}

function Tooltip({
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Root>) {
  return (
    <TooltipProvider>
      <TooltipPrimitive.Root data-slot="tooltip" {...props} />
    </TooltipProvider>
  )
}

function TooltipTrigger({
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Trigger>) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />
}

function TooltipContent({
  className,
  sideOffset = 0,
  children,
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Content>) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Content
        data-slot="tooltip-content"
        sideOffset={sideOffset}
        className={cn(
          "bg-foreground text-background animate-in fade-in-0 zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 z-50 w-fit origin-(--radix-tooltip-content-transform-origin) rounded-md px-3 py-1.5 text-xs text-balance",
          className
        )}
        {...props}
      >
        {children}
        <TooltipPrimitive.Arrow className="bg-foreground fill-foreground z-50 size-2.5 translate-y-[calc(-50%_-_2px)] rotate-45 rounded-[2px]" />
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  )
}

export { Tooltip, TooltipTrigger, TooltipContent, TooltipProvider }
